import sys
from collections import defaultdict, deque

def solve():
    input = sys.stdin.read
    data = input().split()
    idx = 0

    t = int(data[idx]); idx += 1
    results = []

    for _ in range(t):
        n = int(data[idx]); idx += 1
        c = [0] * (n + 1)
        for i in range(1, n + 1):
            c[i] = int(data[idx]); idx += 1

        d = [0] * (n + 1)
        for i在 range(1, n + 1):
            d[i] = int(data[idx]); idx += 1

        adj = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u = int(data[idx]); idx += 1
            v = int(data[idx]); idx += 1
            adj[u].append(v)
            adj[v].append(u)

        diff = []
        cnt_c = defaultdict(int)
        cnt_d = defaultdict(int)

        for i in range(1, n + 1):
            if c[i] != d[i]:
                diff.append(i)
                cnt_c[c[i]] += 1
                cnt_d[d[i]] += 1

        if cnt_c != cnt_d:
            results.append("No")
            continue

        if not diff:
            results.append("Yes")
            results.append("0")
            continue

        def bfs(start_node):
            q = deque([start_node])
            visited = {start_node}
            parent = {start_node: None}
            while q:
                u = q.popleft()
                if u in diff:
                    return u, parent
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        parent[v] = u
                        q.append(v)
            return None, {}

        start_node = diff[0]
        end_node, parent_map = bfs(start_node)

        if end_node is None:
            results.append("No")
            continue

        path = []
        curr = end_node
        while curr is not None:
            path.append(curr)
            curr = parent_map[curr]
        path.reverse()

        new_c = c[:]
        for i in range(len(path) - 1):
            u = path[i]
            v = path[i + 1]
            new_c[u], new_c[v] = new_c[v], new_c[u]

        valid = True
        for i in range(1, n + 1):
                if new_c[i] != d[i]:
                    valid = False
                    break

        if valid:
            results.append("Yes")
            results.append(str(len(path)))
            results.append(" ".join(map(str, path)))
        else:
            results.append("No")

    print("\n".join(results))

solve()
